import {useEffect,useState} from 'react';
import {BadgeCheck,BarChart3,ExternalLink,FileCheck2,Inbox,RefreshCw,Star,UsersRound} from 'lucide-react';
import {actOnMarketplaceEnrolment,addMarketplaceQualification,getMarketplaceEarnings,getMarketplaceProfile,getMarketplaceReadiness,listMarketplaceEnrolments,listMarketplaceReviews,reportMarketplaceReview,saveMarketplaceProfile,submitMarketplaceProfile} from '../../lib/practiceOperationsApi';
import {Button,FeedbackState,Input,LoadingSkeleton,ProgressBar,StatusChip,Surface,TextArea} from './ui/ExternalUI';

const EMPTY={display_name:'',professional_title:'',profession_code:'',profile_photo_url:'',specialisations:[],experience_years:0,bio:'',languages:[],consultation_modes:['ONLINE'],areas_of_focus:[],public_locations:[],services:[],programmes:[],session_duration:60,public_fee_from:null,accepting_new_clients:false};
const split=value=>value.split(',').map(item=>item.trim()).filter(Boolean);
export function ExternalMarketplace(){const[state,setState]=useState('loading');const[data,setData]=useState(null);const[readiness,setReadiness]=useState(null);const[form,setForm]=useState(EMPTY);const[tab,setTab]=useState('profile');const[message,setMessage]=useState('');const[enrolments,setEnrolments]=useState(null);const[reviews,setReviews]=useState(null);const[earnings,setEarnings]=useState(null);
  const load=()=>{setState('loading');Promise.all([getMarketplaceProfile(),getMarketplaceReadiness()]).then(([value,ready])=>{setData(value);setReadiness(ready);setForm({...EMPTY,...(value.version?.projection||{})});setState('ready')}).catch(error=>{setMessage(error.message);setState('error')})};useEffect(load,[]);
  const save=async()=>{setMessage('');try{const result=await saveMarketplaceProfile(form);setMessage(`Draft version ${result.version} saved.`);await load()}catch(error){setMessage(error.message)}};
  const submit=async()=>{setMessage('');try{await submitMarketplaceProfile();setMessage('Submitted for Super Admin review. Approval will not publish the profile.');await load()}catch(error){setMessage(error.message)}};
  const showEnrolments=async()=>{setTab('enrolments');if(!enrolments)try{setEnrolments(await listMarketplaceEnrolments())}catch(error){setMessage(error.message)}};
  const showReviews=async()=>{setTab('reviews');if(!reviews)try{setReviews(await listMarketplaceReviews())}catch(error){setMessage(error.message)}};
  const showEarnings=async()=>{setTab('earnings');setEarnings(null);try{setEarnings(await getMarketplaceEarnings())}catch(error){setEarnings({state:'FAILED_TO_LOAD',message:error.message})}};
  if(state==='loading')return <LoadingSkeleton height="32rem" label="Loading marketplace profile"/>;if(state==='error')return <FeedbackState kind="error" title="Marketplace profile unavailable" copy={`${message}. No zero metrics are inferred.`} action={<Button icon={RefreshCw} onClick={load}>Retry</Button>}/>;
  const profile=data.profile;const version=data.version;const analytics=data.analytics;return <div className="space-y-5"><header className="flex flex-col justify-between gap-4 rounded-3xl bg-slate-950 p-6 text-white sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-widest text-cyan-300">Consultant marketplace</p><h2 className="mt-2 text-3xl font-bold">Public profile</h2><p className="mt-2 text-sm text-slate-300">Private draft → review → approval → explicit publication. Approved does not mean published.</p></div><div><p className="mb-1 text-xs text-slate-300">Publication status</p><StatusChip tone={profile?.status==='PUBLISHED'?'success':'info'}>{profile?.status?.replaceAll('_',' ')||'DRAFT'}</StatusChip></div></header>
    <nav aria-label="Marketplace workspace" className="flex gap-2 overflow-x-auto">{[['profile','Public Profile'],['qualifications','Qualifications'],['enrolments','Enrolments'],['reviews','Reviews & Analytics'],['earnings','Marketplace Earnings']].map(([id,label])=><button key={id} onClick={()=>id==='enrolments'?showEnrolments():id==='reviews'?showReviews():id==='earnings'?showEarnings():setTab(id)} className={`min-h-11 shrink-0 rounded-xl px-4 text-sm font-bold ${tab===id?'bg-blue-700 text-white':'border bg-white'}`}>{label}</button>)}</nav>{message&&<p role="status" className="rounded-xl bg-blue-50 p-3 text-sm text-blue-900">{message}</p>}
    {tab==='profile'&&<div className="grid gap-5 xl:grid-cols-[1fr_320px]"><Surface><h3 className="text-xl font-bold">Profile draft</h3><div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Display name"><Input value={form.display_name} onChange={e=>setForm({...form,display_name:e.target.value})}/></Field><Field label="Professional title"><Input value={form.professional_title} onChange={e=>setForm({...form,professional_title:e.target.value})}/></Field><Field label="Profession code"><Input value={form.profession_code} onChange={e=>setForm({...form,profession_code:e.target.value.toUpperCase()})}/></Field><Field label="Experience years"><Input type="number" min="0" value={form.experience_years} onChange={e=>setForm({...form,experience_years:Number(e.target.value)})}/></Field><Field label="Specialisations"><Input value={form.specialisations.join(', ')} onChange={e=>setForm({...form,specialisations:split(e.target.value)})}/></Field><Field label="Languages"><Input value={form.languages.join(', ')} onChange={e=>setForm({...form,languages:split(e.target.value)})}/></Field><Field label="Consultation modes"><Input value={form.consultation_modes.join(', ')} onChange={e=>setForm({...form,consultation_modes:split(e.target.value).map(v=>v.toUpperCase())})}/></Field><Field label="Session duration"><Input type="number" min="10" value={form.session_duration||''} onChange={e=>setForm({...form,session_duration:Number(e.target.value)})}/></Field><Field label="Profile photo approved public derivative"><Input value={form.profile_photo_url||''} onChange={e=>setForm({...form,profile_photo_url:e.target.value})}/><small className="mt-1 block font-normal text-slate-500">Upload the source privately in Document Vault; paste only its approved public derivative. Raw object keys are rejected.</small></Field><Field wide label="Bio"><TextArea rows="6" value={form.bio} onChange={e=>setForm({...form,bio:e.target.value})}/></Field><Field label="Areas of focus"><Input value={form.areas_of_focus.join(', ')} onChange={e=>setForm({...form,areas_of_focus:split(e.target.value)})}/></Field><Field label="Fee from (minor units)"><Input type="number" min="0" value={form.public_fee_from??''} onChange={e=>setForm({...form,public_fee_from:e.target.value===''?null:Number(e.target.value)})}/></Field><label className="flex min-h-12 items-center gap-3 rounded-xl border p-3 text-sm font-bold"><input type="checkbox" checked={form.accepting_new_clients} onChange={e=>setForm({...form,accepting_new_clients:e.target.checked})}/>Accepting new clients</label></div><CatalogBuilder readiness={readiness} form={form} setForm={setForm}/><div className="mt-6 flex flex-wrap gap-3"><Button variant="primary" onClick={save}>Save draft</Button><Button onClick={submit} disabled={!version||version.completeness<100||['SUBMITTED_FOR_REVIEW','UNDER_REVIEW'].includes(profile?.status)}>Submit for review</Button>{profile?.slug&&<a className="inline-flex min-h-11 items-center gap-2 rounded-xl border px-4 text-sm font-bold" href={`/consultants/${profile.slug}`} target="_blank" rel="noreferrer">Preview <ExternalLink size={16}/></a>}</div></Surface><Surface><h3 className="font-bold">Profile completeness</h3><div className="mt-4"><ProgressBar value={version?.completeness||0} label="Deterministic completeness"/></div><ul className="mt-4 space-y-2 text-sm">{(version?.missing_fields||[]).map(item=><li key={item} className="rounded-lg bg-amber-50 p-2 text-amber-900">Missing: {item}</li>)}</ul><p className="mt-5 text-xs text-slate-500">Published versions remain immutable. Editing a live profile creates a new draft while the current version stays public.</p></Surface></div>}
    {tab==='qualifications'&&<Qualifications items={data.qualifications||[]} onDone={load} onMessage={setMessage}/>}
    {tab==='enrolments'&&<Surface><h3 className="text-xl font-bold">New enrolment requests</h3>{enrolments===null?<LoadingSkeleton/>:enrolments.state==='CONFIRMED_EMPTY'?<FeedbackState title="No confirmed enrolment requests" copy="A failed request is never shown as an empty inbox."/>:<div className="mt-4 divide-y">{enrolments.items.map(item=><article key={item.id} className="py-4"><div className="flex flex-wrap items-center justify-between gap-2"><strong>{item.full_name}</strong><StatusChip>{item.status}</StatusChip></div><p className="mt-1 text-sm text-slate-500">{item.consultation_mode||'Mode not selected'} · {item.preferred_at?new Date(item.preferred_at).toLocaleString():'No preferred slot'}</p><div className="mt-3 flex flex-wrap gap-2"><Button size="small" onClick={()=>location.hash='leads'}>Open lead</Button>{[['Contact','CONTACT'],['Accept','ACCEPT'],['Book','BOOK'],['Decline','DECLINE'],['Convert','CONVERT']].map(([label,action])=><Button key={action} size="small" onClick={async()=>{try{await actOnMarketplaceEnrolment(item.id,action);setMessage(`${label} completed.`);setEnrolments(await listMarketplaceEnrolments())}catch(error){setMessage(error.message)}}}>{label}</Button>)}</div></article>)}</div>}</Surface>}
    {tab==='reviews'&&<><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[[BarChart3,'Profile views',analytics?.profile_views],[UsersRound,'Enrolments',analytics?.enrolments?.total],[Star,'Verified reviews',analytics?.review_count],[BadgeCheck,'Average rating',analytics?.average_rating||'New on Zestiva']].map(([Icon,label,value])=><Surface key={label}><Icon className="text-blue-700"/><p className="mt-4 text-sm text-slate-500">{label}</p><strong className="mt-1 block text-2xl">{value??'—'}</strong></Surface>)}</div><Surface><h3 className="text-xl font-bold">Review history</h3>{reviews?.state==='CONFIRMED_EMPTY'?<FeedbackState title="No verified reviews yet" copy="A failed review request is never rendered as zero."/>:<div className="mt-4 divide-y">{reviews?.items?.map(item=><article key={item.id} className="py-4"><div className="flex justify-between"><strong>{item.overall_rating}/5</strong><StatusChip>{item.status}</StatusChip></div><p className="mt-2 text-sm">{item.review_text||'No written review.'}</p><Button size="small" onClick={async()=>{const reason=window.prompt('Why should Super Admin review this item?');if(reason){await reportMarketplaceReview(item.id,reason);setMessage('Review reported for independent moderation.');setReviews(await listMarketplaceReviews())}}}>Report review</Button></article>)}</div>}</Surface></>}
    {tab==='earnings'&&<MarketplaceEarnings data={earnings} retry={showEarnings}/>}
  </div>}
function MarketplaceEarnings({data,retry}){if(!data)return <LoadingSkeleton label="Loading marketplace earnings"/>;if(data.state==='FAILED_TO_LOAD')return <FeedbackState kind="error" title="Earnings unavailable" copy={`${data.message}. No zero earnings are inferred.`} action={<Button onClick={retry}>Retry</Button>}/>;const currency=data.currency||'—';return <div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">{[['Gross',data.gross_minor],['Platform Fees',data.platform_fee_minor],['Net Earnings',data.net_earnings_minor],['Pending Payout',data.pending_payout_minor],['Paid Payout',data.paid_payout_minor]].map(([label,value])=><Surface key={label}><p className="text-sm text-slate-500">{label}</p><strong className="mt-2 block text-2xl">{data.state==='CONFIRMED_EMPTY'?'No recorded activity':`${currency} ${value}`}</strong></Surface>)}</div><p className="mt-4 text-sm text-slate-500">Amounts are deterministic minor-unit ledger projections. Paid means settlement evidence exists.</p></div>}
function Field({label,wide,children}){return <label className={`text-sm font-bold ${wide?'sm:col-span-2':''}`}>{label}<span className="mt-2 block">{children}</span></label>}
function Qualifications({items,onDone,onMessage}){const[form,setForm]=useState({qualification_type:'DEGREE',title:'',institution:'',award_year:new Date().getFullYear(),country:'',registration_number:'',issuing_body:'',expiry_date:'',credential_document_id:''});const add=async()=>{try{await addMarketplaceQualification({...form,expiry_date:form.expiry_date||null,credential_document_id:form.credential_document_id||null});onMessage('Qualification added for independent verification.');onDone()}catch(error){onMessage(error.message)}};return <div className="grid gap-5 lg:grid-cols-2"><Surface><h3 className="text-xl font-bold">Add qualification</h3><div className="mt-4 space-y-3">{[['title','Degree / title'],['institution','Institution'],['award_year','Year'],['country','Country'],['registration_number','Registration number'],['issuing_body','Issuing body'],['expiry_date','Expiry date'],['credential_document_id','Private vault document ID']].map(([key,label])=><Field key={key} label={label}><Input type={key==='award_year'?'number':key==='expiry_date'?'date':'text'} value={form[key]} onChange={e=>setForm({...form,[key]:key==='award_year'?Number(e.target.value):e.target.value})}/></Field>)}<Button variant="primary" onClick={add}>Add credential</Button></div></Surface><Surface><h3 className="text-xl font-bold">Verification</h3>{items.length?<div className="mt-4 divide-y">{items.map(item=><article className="py-3" key={item.id}><div className="flex justify-between gap-3"><strong>{item.title}</strong><StatusChip tone={item.verification_status==='VERIFIED'?'success':'neutral'}>{item.verification_status}</StatusChip></div><p className="mt-1 text-sm text-slate-500">{item.institution} · {item.award_year}</p><p className="mt-1 text-xs text-slate-400">Evidence remains private in Document Vault.</p></article>)}</div>:<FeedbackState title="No qualifications added" copy="At least one independently verified qualification is required for profile completeness."/>}</Surface></div>}
function CatalogBuilder({readiness,form,setForm}){const addService=id=>{const source=readiness?.appointment_types?.find(item=>String(item.id)===id);if(!source||form.services.some(item=>String(item.id)===id))return;setForm({...form,services:[...form.services,{id:String(source.id),name:source.name,description:source.description,duration:source.duration_minutes,mode:source.location_type,location_id:null,fee:null,enrolment_mode:'REQUEST_ENROLMENT',active:true}]})};const addProgramme=id=>{const source=readiness?.packages?.find(item=>String(item.id)===id);if(!source||form.programmes.some(item=>String(item.id)===id))return;setForm({...form,programmes:[...form.programmes,{id:String(source.id),name:source.name,description:source.description,fee:source.price_minor,active:true}]})};const addLocation=id=>{const source=readiness?.locations?.find(item=>String(item.id)===id);if(!source||form.public_locations.some(item=>String(item.id)===id))return;setForm({...form,public_locations:[...form.public_locations,{id:String(source.id),name:source.name,mode:'IN_PERSON'}]})};return <section className="mt-6 rounded-2xl bg-slate-50 p-4"><h4 className="font-bold">Governed catalogue</h4><p className="mt-1 text-xs text-slate-500">Select existing P13 services, P12 programmes and P26 locations. This does not create duplicate catalogue records.</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><select aria-label="Add governed service" defaultValue="" onChange={e=>{addService(e.target.value);e.target.value=''}} className="min-h-11 rounded-xl border bg-white px-3"><option value="">Add service…</option>{readiness?.appointment_types?.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><select aria-label="Add governed programme" defaultValue="" onChange={e=>{addProgramme(e.target.value);e.target.value=''}} className="min-h-11 rounded-xl border bg-white px-3"><option value="">Add programme…</option>{readiness?.packages?.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><select aria-label="Add governed location" defaultValue="" onChange={e=>{addLocation(e.target.value);e.target.value=''}} className="min-h-11 rounded-xl border bg-white px-3"><option value="">Add location…</option>{readiness?.locations?.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></div><p className="mt-3 text-xs">Services: {form.services.map(x=>x.name).join(', ')||'none'} · Programmes: {form.programmes.map(x=>x.name).join(', ')||'none'} · Locations: {form.public_locations.map(x=>x.name).join(', ')||'online only'} · Availability windows: {readiness?.availability?.length??'unavailable'}</p></section>}
